{"fn": "() => {
  const all = document.querySelectorAll('*');
  const results = [];
  all.forEach(el => {
    if (el.tagName === 'SCRIPT' || el.tagName === 'STYLE') return;
    const text = el.innerText?.trim();
    if (text && (text.includes('vendor') || text.includes('Northstar') || text.includes('Kepler') || text.includes('$') || text.includes('Sep'))) {
      if (text.length < 500) {
        results.push({tag: el.tagName, text: text.substring(0, 300), className: el.className});
      }
    }
  });
  return JSON.stringify(results.slice(0, 30), null, 2);
}"}

